-- BACKUP: bak_20261105_e_issue_notes_3
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261105_e_issue_notes_3 b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261105_e_issue_notes_3)
-- CAUSE-MAPPED: no metric is registered here; this appends one dated finding to the description of METRIC-354 (agent_issues 1000988, workers_ai_cost_30d_usd).
-- The note carries no task, anchor or probe line, so no planner is handed a second copy of work another issue owns.

CREATE TABLE IF NOT EXISTS bak_20261105_e_issue_notes_3 AS SELECT id, description FROM agent_issues WHERE id IN (1000988);

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05c (METRIC-354, GitHub 6171): read at 04:05Z. workers_ai_cost_30d_usd reads 518.72 against 95 (v_metric_trigger_state 354). qnfo-research-exec is still the first worker by counted neurons (ai_call_counters, 2026-11-03 to 11-05: 1,560,634, then qnfo-agents 955,531 and qnfo-code-orchestrator 619,933), and gpt-oss-120b is 47.3 percent (11-02), 40.8 percent (11-03) and 47.2 percent (11-04) of its neurons, so the escalation this issue names persists. Two things changed since it was filed that the proposed levers do not account for. (1) RESEARCH-REVISE-RELIABLE-1 (0.48.0, owner directive 2026-11-04, free models are only good if they work) put gpt-oss-120b first on the revise call because glm-5.3-flash failed 253 of 857 revise calls, and GPT-OSS-EFFORT-LOW-1 (0.49.2) lowered the reasoning effort of each gpt-oss call (its effect on neurons per call was not measured here); an empty or failed glm reply is the signal both acted on, so removing the escalation without a per-purpose measure of the empty-reply share would trade neurons for failed calls, and the narrow code task needs that measure before it ships. (2) The budget cut the issue proposes, ops_config research_daily_neurons 360000 to 150000, is below the floor of the reader-linked rule: v_research_volume_target reads 4.67 externally sourced engaged readers a day, target 298,667, next step 324,000, floor 180,000, ceiling 450,000, governor off; qnfo-ops is the single writer of that key, so the cut is the READER-YIELD-1.5 governor switch and not a session write. The largest fleet-wide drivers measured on 2026-11-04 and 11-05 are other streams (gateway article rebuilds about 500,000 neurons a day, companion retries, program-manager requests), handled by COST-LEVERS-1 (PR 7628) and the spend-enforcement changes. Not done here: qnfo-research-exec/worker.js was under another code-loop claim (ct_im1001450) at the time of this read. Closing probe: this issue contract (workers_ai_cost_30d_usd under its threshold).'
WHERE id = 1000988 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05c') = 0;
